/* Buyer email lookups (round rel-db). Two trigram indexes for the reads that find a buyer's orders or checkouts by email inside one store: creator_id = X and buyer_email ILIKE the address (the storefront account and order pages, order lookup by email and number, access links, checkout's already owned check, the Email area). The btree on buyer_email and the one on lower(buyer_email) cannot serve ILIKE, so each of those reads walked every order or checkout of the store; a GIN index with gin_trgm_ops serves ILIKE of an exact address. pg_trgm is made where it is available (in the extensions schema when there is one), as part 342 does; without it the part skips with a notice and the reads work as before, without an index. No row changes, no policy or function changes. LOCKS: a plain CREATE INDEX stops writes to orders and commerce_checkouts while it builds and the editor holds that to the end of the paste; on a large database run supabase/sql/RUN_BUYER_EMAIL_TRGM_CONCURRENTLY.sql first, ONE LINE PER RUN or with psql -f (CREATE INDEX CONCURRENTLY cannot run inside a transaction, and the editor runs a paste as one), and this part then finds each index made and builds nothing. Each index is made only when its table and column are there. Safe to run again. */
DO $do$ DECLARE sch text; BEGIN IF to_regclass('public.orders') IS NULL THEN RAISE NOTICE 'part 349: orders_buyer_email_trgm_idx skipped, public.orders does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'buyer_email') THEN RAISE NOTICE 'part 349: orders_buyer_email_trgm_idx skipped, public.orders has no buyer_email'; RETURN; END IF; IF to_regclass('public.orders_buyer_email_trgm_idx') IS NOT NULL THEN RETURN; END IF; SELECT n.nspname INTO sch FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'pg_trgm'; IF sch IS NULL AND EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_trgm') THEN IF to_regnamespace('extensions') IS NOT NULL THEN CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA extensions; sch := 'extensions'; ELSE CREATE EXTENSION IF NOT EXISTS pg_trgm; SELECT n.nspname INTO sch FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'pg_trgm'; END IF; END IF; IF sch IS NULL THEN RAISE NOTICE 'part 349: pg_trgm is not available, orders_buyer_email_trgm_idx skipped: lookups by email work, without an index'; RETURN; END IF; EXECUTE format('CREATE INDEX IF NOT EXISTS orders_buyer_email_trgm_idx ON public.orders USING gin (buyer_email %I.gin_trgm_ops) WHERE buyer_email IS NOT NULL', sch); END $do$;
DO $do$ DECLARE sch text; BEGIN IF to_regclass('public.commerce_checkouts') IS NULL THEN RAISE NOTICE 'part 349: commerce_checkouts_buyer_email_trgm_idx skipped, public.commerce_checkouts does not exist here'; RETURN; END IF; IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'commerce_checkouts' AND column_name = 'buyer_email') THEN RAISE NOTICE 'part 349: commerce_checkouts_buyer_email_trgm_idx skipped, public.commerce_checkouts has no buyer_email'; RETURN; END IF; IF to_regclass('public.commerce_checkouts_buyer_email_trgm_idx') IS NOT NULL THEN RETURN; END IF; SELECT n.nspname INTO sch FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'pg_trgm'; IF sch IS NULL AND EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'pg_trgm') THEN IF to_regnamespace('extensions') IS NOT NULL THEN CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA extensions; sch := 'extensions'; ELSE CREATE EXTENSION IF NOT EXISTS pg_trgm; SELECT n.nspname INTO sch FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'pg_trgm'; END IF; END IF; IF sch IS NULL THEN RAISE NOTICE 'part 349: pg_trgm is not available, commerce_checkouts_buyer_email_trgm_idx skipped: lookups by email work, without an index'; RETURN; END IF; EXECUTE format('CREATE INDEX IF NOT EXISTS commerce_checkouts_buyer_email_trgm_idx ON public.commerce_checkouts USING gin (buyer_email %I.gin_trgm_ops) WHERE buyer_email IS NOT NULL', sch); END $do$;
notify pgrst, 'reload schema';
